import{_ as t,c as a,o as s,a4 as e}from"./chunks/framework.DzOtv0XR.js";const x=JSON.parse('{"title":"Tmux","description":"","frontmatter":{},"headers":[],"relativePath":"tools/tmux.md","filePath":"tools/tmux.md"}'),n={name:"tools/tmux.md"},p=e(`<h1 id="tmux" tabindex="-1">Tmux <a class="header-anchor" href="#tmux" aria-label="Permalink to &quot;Tmux&quot;">​</a></h1><p>[toc]</p><p><a href="http://man.openbsd.org/OpenBSD-current/man1/tmux.1" target="_blank" rel="noreferrer">tmux(1) - OpenBSD manual pages</a></p><blockquote><p>server &lt;=&gt; client =&gt; session =&gt; pane =&gt; window</p></blockquote><h2 id="cheatsheet" tabindex="-1">cheatsheet <a class="header-anchor" href="#cheatsheet" aria-label="Permalink to &quot;cheatsheet&quot;">​</a></h2><table><thead><tr><th>功能</th><th>按键</th></tr></thead><tbody><tr><td>前缀键</td><td>ctrl+k</td></tr><tr><td>新建窗口/会话</td><td>c/shift-c</td></tr><tr><td>水平分割</td><td>&quot;（两个点）</td></tr><tr><td>垂直分割</td><td>%（两个圈）</td></tr><tr><td>切换窗口</td><td>o</td></tr><tr><td>调换窗口</td><td>ctrl+o</td></tr><tr><td>调整大小</td><td>ctrl+方向键</td></tr><tr><td>列出所有窗口</td><td>w</td></tr><tr><td>关闭当前窗口</td><td>&amp;</td></tr><tr><td>关闭 pane</td><td>x</td></tr><tr><td>显示 pane 编号</td><td>q</td></tr><tr><td>切换 pane</td><td>;</td></tr><tr><td>查找 window</td><td>f</td></tr><tr><td>last window</td><td>ctrl+l</td></tr><tr><td>独立为新窗口</td><td>!</td></tr><tr><td>列出所有 session</td><td>s</td></tr><tr><td>切换 session</td><td>()</td></tr><tr><td>放大当前窗口/恢复</td><td>z</td></tr></tbody></table><p>前缀键改为 <code>ctrl+k</code>，进入命令模式输入：<code>set -g prefix ^k</code><a href="https://gist.github.com/MohamedAlaa/2961058" target="_blank" rel="noreferrer">tmux shortcuts &amp; cheatsheet</a></p><h2 id="滚屏模式" tabindex="-1">滚屏模式 <a class="header-anchor" href="#滚屏模式" aria-label="Permalink to &quot;滚屏模式&quot;">​</a></h2><p>默认状态下不能滚屏，进入：前缀键 + [ 滚动：vi 按键风络或上下方向键或 PgUp/PgDown 复制：<code>prefix -&gt; [ -&gt; v -&gt; y -&gt; q</code> 粘贴：<code>prefix -&gt; ]</code></p><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span># 创建会话</span></span>
<span class="line"><span>tmux new -s [NAME]</span></span>
<span class="line"><span># 挂载会话</span></span>
<span class="line"><span>tmux attach</span></span>
<span class="line"><span># 分离会话</span></span>
<span class="line"><span>tmux detach</span></span>
<span class="line"><span># 列出会话</span></span>
<span class="line"><span>tmux ls</span></span>
<span class="line"><span># 杀掉会话</span></span>
<span class="line"><span>tmux kill-session -t [ID]</span></span>
<span class="line"><span># 保存会话</span></span>
<span class="line"><span>\`prefix ctrl s\`</span></span>
<span class="line"><span># 恢复会话</span></span>
<span class="line"><span>\`prefix ctrl r\`</span></span></code></pre></div><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><p>安装插件管理器</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>git clone https://github.com/tmux-plugins/tpm ~/.tmux/plugins/tpm</span></span>
<span class="line"><span>tmux source ~/.tmux.conf</span></span></code></pre></div><p>在配置中写入插件地址，然后在 Tmux 中按下 <code>prefix - I</code>，安装, <code>prefix - U</code>，更新, <code>prefix - alt - u</code>，卸载，注意这里是小写 u,</p><p><a href="https://linuxtoy.org/archives/tmux-resurrect-and-continuum.html" target="_blank" rel="noreferrer">Tmux Resurrect &amp; Continuum: 持久保存 Tmux 会话 · LinuxTOY</a></p><p>快速创建 session <code>prefix - C</code> 杀掉建 session <code>prefix - X</code></p><h2 id="issues" tabindex="-1">issues <a class="header-anchor" href="#issues" aria-label="Permalink to &quot;issues&quot;">​</a></h2><h3 id="大屏访问小屏时-修正窗口尺寸" tabindex="-1">大屏访问小屏时，修正窗口尺寸 <a class="header-anchor" href="#大屏访问小屏时-修正窗口尺寸" aria-label="Permalink to &quot;大屏访问小屏时，修正窗口尺寸&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>在大屏的 tmux 中</span></span>
<span class="line"><span>prefix - D</span></span>
<span class="line"><span>detach 掉时间较旧的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>或者</span></span>
<span class="line"><span>tmux list-client</span></span>
<span class="line"><span>tmux detach-client -s 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>或者 detach 掉除当前外的所有</span></span>
<span class="line"><span>tmux detach -a</span></span></code></pre></div><h3 id="kill-session" tabindex="-1">kill session <a class="header-anchor" href="#kill-session" aria-label="Permalink to &quot;kill session&quot;">​</a></h3><ol><li>切换到窗口列表</li><li>焦点移动到要杀掉的 session</li><li>依次按下<code>q</code> <code>y</code> <code>enter</code></li></ol><h3 id="窗口意外退出" tabindex="-1">窗口意外退出 <a class="header-anchor" href="#窗口意外退出" aria-label="Permalink to &quot;窗口意外退出&quot;">​</a></h3><p>是因为触发终端退出</p><p><a href="https://superuser.com/questions/479600/how-can-i-prevent-tmux-exiting-with-ctrl-d" target="_blank" rel="noreferrer">shell - How can I prevent tmux exiting with Ctrl-d? - Super User</a></p><h3 id="debug" tabindex="-1">debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;debug&quot;">​</a></h3><p><code>tmux -v</code> 启动，当前目录生成日志</p>`,27),d=[p];function r(l,i,o,c,h,u){return s(),a("div",null,d)}const g=t(n,[["render",r]]);export{x as __pageData,g as default};
